CREATE OR REPLACE FUNCTION public.rpc_confirm_order_received(p_order_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$ DECLARE v_user_id text; v_order record; BEGIN v_user_id := auth.uid()::text; IF v_user_id IS NULL THEN RAISE EXCEPTION 'Usuario no autenticado'; END IF; IF is_banned() THEN RAISE EXCEPTION 'El usuario esta suspendido'; END IF; SELECT * INTO v_order FROM public.pedidos WHERE id = p_order_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Pedido no encontrado'; END IF; IF v_order.user_id <> v_user_id AND NOT is_admin_email() THEN RAISE EXCEPTION 'Acceso denegado: no eres el propietario de este pedido'; END IF; IF v_order.estado IN ('entregado', 'recibido', 'cancelado') THEN RAISE EXCEPTION 'El pedido ya fue finalizado previamente'; END IF; IF v_order.estado NOT IN ('asignado', 'pendiente', 'visto') THEN RAISE EXCEPTION 'El pedido no se encuentra en un estado valido para confirmar'; END IF; UPDATE public.pedidos SET estado = 'recibido', updated_at = NOW() WHERE id = p_order_id; RETURN jsonb_build_object('success', true, 'message', 'Pedido recibido confirmado'); END; $$;
